{
  "headline": "FDA's records trace our supply to plants with OAI classifications and warning letters before the shortage posting",
  "headline_cites": ["D4", "D8", "D9", "D17", "D18"],
  "sentences": [
    {
      "text": "FDA first posted the sterile water shortage on 2021-11-23 and it has remained current for 59 months as of 2026-10-21.",
      "cites": ["E84", "D23"]
    },
    {
      "text": "An FDA inspection of Pfizer Healthcare India Private Limited ended 2019-09-06 and was classified OAI, with the classification letter dated 2020-05-25 — 547 days before the shortage posting.",
      "cites": ["D4", "D18", "E38"]
    },
    {
      "text": "FDA issued a Warning Letter to Pfizer Healthcare India Private Limited on 2020-03-25 — 608 days before the shortage posting.",
      "cites": ["D8", "E40"]
    },
    {
      "text": "FDA issued a Warning Letter to Nephron SC, LLC on 2020-09-22 — 427 days before the shortage posting.",
      "cites": ["D9", "E70"]
    },
    {
      "text": "FDA's OAI classification letter to Hospira, Inc. is dated 2020-04-22 — 580 days before the shortage posting.",
      "cites": ["D17", "E28"]
    },
    {
      "text": "The rule-identified best option is to buy from American Regent, Inc., which is not on FDA's shortage list today and whose plant last received a VAI classification on 2024-04-24.",
      "cites": ["D20"]
    }
  ]
}
